def solve(clue):
    x, P = 0, 1
    for t in clue.split():
        a, b = t.split('%')
        r, m = int(a), int(b)
        # merge x (mod P) with r (mod m); P and m coprime
        k = 0
        while (x + P * k) % m != r:
            k += 1
        x = x + P * k
        P = P * m
    return str(x)

